#include <stdio.h>

int main() {
    int grid[2][2] = {{1, 2}, {3, 4}};
    int target = 3;
    int found = 0;
    for (int i = 0; i < 2 && !found; i++) {
        for (int j = 0; j < 2; j++) {
            if (grid[i][j] == target) {
                found = 1;
                break;
            }
        }
        printf("Checked row %d\n", i);
    }
    return 0;
}
